import type { Question } from "@/lib/types";

// Coverage inspired by topics tested in Dr. David's AIGP question-of-the-day series (Oct 2026);
// all stems, scenarios and options are original.
function o(label: string, text: string, isCorrect = false, sort = 0) {
  return { label, text, isCorrect, sort };
}

const raw: Array<{
  id: string; c: string; type: Question["type"]; d: 1 | 2 | 3; stem: string;
  opts: [string, boolean][]; why: string; wrong?: Record<string, string>;
  strat?: string; trap?: Question["trapType"]; bok: string; multi?: boolean;
}> = [
  // ───────── A. EU AI Act — operators, enforcement, lifecycle ─────────

  // F1 — one operator, multiple roles
  { id: "e-ddl-1", c: "ii-c", type: "best", d: 3, stem: "Veltara Mobility, established in Rotterdam, develops a route-risk scoring system, places it on the EU market under its own trademark, and also runs the same system in-house to dispatch its own couriers across Belgium. Counsel is asked how the EU AI Act characterises the company. Which analysis is correct?", opts: [["Veltara holds two operator roles at once — provider of the system it places on the market, and deployer for its own in-house dispatch use — with each role's obligations applying to it", true], ["Veltara is a provider only, because the Act assigns each operator exactly one role per AI system", false], ["Veltara's heaviest obligations flow from its deployer role, since deployers are the most heavily regulated operators under the Act", false], ["Veltara is an importer, a role reserved for operators established outside the Union that bring systems in", false]], why: "AI Act roles are not mutually exclusive: the same operator can be provider and deployer of the same system at the same time, and must satisfy each role's duties. Veltara placed the system on the market under its own trademark (provider) and uses it under its own authority (deployer).", wrong: { B: "Invents a one-role-per-actor rule the Act does not contain — the absolute 'exactly one' is the tell.", C: "Backwards: providers carry the Act's most extensive obligations; deployer duties are comparatively lighter.", D: "Doubly wrong — importers are established IN the Union and place on the market systems bearing a non-EU person's name or trademark; nothing here was imported." }, strat: "When one company both builds-and-markets and uses a system, test each role separately — roles stack, they do not replace each other.", trap: "absolute", bok: "Domain II, Competency C" },

  // F2 — importer definition
  { id: "e-ddl-2", c: "ii-c", type: "role", d: 3, stem: "Cordet BV, established in Belgium, buys a workforce-rostering AI from Quorix Pte Ltd of Singapore and places it on the EU market for the first time, unmodified and still bearing Quorix's trademark. Under the EU AI Act, Cordet is acting as:", opts: [["an importer — an operator established in the Union that places on the market an AI system bearing the name or trademark of a person established outside the Union", true], ["a distributor, because it merely passes a finished system along the supply chain", false], ["Quorix's authorised representative, a status that attaches automatically to the first EU reseller", false], ["the provider, because whoever places a system on the EU market always takes provider status", false]], why: "The importer definition has two hooks and Cordet meets both: it is established in the Union, and the system it places on the market carries the mark of a person established outside the Union.", wrong: { B: "Distributors make systems available AFTER they are already on the market; the operator that first places a foreign-branded system on the market is the importer — classic neighbour-term bait.", C: "An authorised representative exists only through a written mandate from the provider; the status never attaches automatically.", D: "Placing on the market confers provider status only when done under one's OWN name or trademark (or after substantial modification); Quorix's mark stayed on the system." }, strat: "Supply-chain role items turn on two facts: where is the operator established, and whose trademark is on the system. Fix both before reading the options.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F3 — Art. 25: substantial modification flips the role
  { id: "e-ddl-3", c: "ii-c", type: "role", d: 3, stem: "Brightparcel, an EU software reseller, takes a vendor's warehouse-scheduling system that is already on the EU market, substantially modifies its decision logic, and resells the result for allocating tasks to and monitoring warehouse employees — a high-risk use. The original vendor's trademark still appears on the start-up screen. Under Article 25 of the EU AI Act, Brightparcel:", opts: [["is now considered the provider of the modified high-risk system and takes on the provider obligations for it", true], ["remains a mere distributor so long as the original vendor's trademark stays visible on the product", false], ["is an importer, because the underlying system was originally developed by someone else", false], ["shares provider status equally with the original vendor for the entire system", false]], why: "Article 25 shifts provider status onto any third party — distributor, importer, deployer or other — that substantially modifies a high-risk system already on the market, puts its own name or trademark on one, or repurposes a system into high-risk use. Substantial modification alone is enough; the surviving trademark does not save Brightparcel.", wrong: { B: "Rebranding is indeed one Article 25 trigger, but that makes the visible vendor mark a red herring here — substantial modification is an independent trigger of its own.", C: "Importer status is about Union establishment plus a non-EU person's mark on first placing; authorship history is not the test.", D: "The Act reallocates the provider role for the modified system; it does not create automatic joint providership with the original vendor." }, strat: "Three events flip a downstream actor into a provider: put your own name on it, substantially modify it, or repurpose it into high-risk. Spot any one and reassign the duties before answering.", trap: "true-but-irrelevant", bok: "Domain II, Competency C" },

  // F4 — importer due diligence (multi-select)
  { id: "e-ddl-4", c: "ii-c", type: "best", d: 3, multi: true, stem: "Nordqvist Handel, established in Denmark, is preparing to place on the EU market a high-risk machine-vision system branded by its Korean developer. Which three verifications does the EU AI Act's importer due-diligence duty require BEFORE Nordqvist places the system on the market? Select THREE.", opts: [["That the provider has carried out the relevant conformity assessment procedure for the system", true], ["That the model has been retrained and revalidated on EU-representative data at Nordqvist's expense", false], ["That the provider has drawn up the required technical documentation", true], ["That Nordqvist has commissioned its own notified body to re-certify the system independently", false], ["That the system bears the required CE marking and is accompanied by the EU declaration of conformity and instructions for use", true]], why: "Importer due diligence is a paperwork-and-markings check: confirm the conformity assessment happened, the technical documentation exists, and the CE marking, declaration of conformity and instructions travel with the system — and that an authorised representative has been appointed. The importer verifies; it does not engineer.", wrong: { B: "Retraining and revalidation are provider engineering duties — assigning them to the importer is the wrong-actor trap dressed up as diligence.", D: "The importer confirms the provider's conformity assessment WAS carried out; it neither repeats nor re-commissions the assessment itself." }, strat: "For each supply-chain actor memorise the verb: providers demonstrate conformity, importers verify it, distributors check the markings. Options that make a downstream actor re-do provider work are planted.", trap: "true-but-irrelevant", bok: "Domain II, Competency C" },

  // F5 — importer discovers a risk: whom to tell
  { id: "e-ddl-5", c: "ii-c", type: "best", d: 3, stem: "During pre-market checks, importer Salvex SA concludes that a high-risk credential-screening system it intended to place on the EU market presents a risk to fundamental rights. Beyond holding the system back until it conforms, whom must Salvex inform?", opts: [["The system's provider and the market surveillance authorities", true], ["Only the business customers that pre-ordered the system", false], ["A notified body, which must then repeat the conformity assessment", false], ["The European AI Office, which handles risk notifications for all national product issues", false]], why: "An importer that considers a high-risk system presents a health, safety or fundamental-rights risk must not place it on the market and must inform the provider and the market surveillance authorities.", wrong: { B: "Customers are not the statutory notification channel, and the system never reaches them if it is withheld — far too narrow a circle.", C: "Notified bodies perform third-party conformity assessments; they are not the recipients of risk notifications from importers.", D: "The AI Office's supervisory remit is general-purpose AI models at EU level, not national product-risk notifications — right-sounding body, wrong job." }, strat: "Keep a who-gets-told table: risk discoveries flow to the provider and the market surveillance authority; notified bodies assess, they are not alarm bells.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F6 + F8 — authorised representative: appointment and escalation duty
  { id: "e-ddl-6", c: "ii-c", type: "best", d: 3, stem: "Tessolve AI, a Toronto developer with no EU establishment, sells its high-risk exam-grading system in the Union through the written mandate the Act requires it to give an EU authorised representative, Veran Compliance GmbH. Veran later forms the view that Tessolve is knowingly placing the system on the market contrary to the AI Act and is ignoring its objections. Veran must:", opts: [["terminate the mandate and inform the relevant market surveillance authority, giving the reasons", true], ["retain the mandate but record its concerns confidentially, since a representative cannot abandon a provider mid-market", false], ["assume Tessolve's provider obligations itself so the system can lawfully remain on the market", false], ["destroy the technical documentation it holds so that it cannot be implicated in the non-compliance", false]], why: "A non-EU provider of high-risk AI must appoint an EU authorised representative by written mandate — and a representative that considers the provider is acting contrary to the Act must terminate that mandate and inform the relevant market surveillance authority of the termination and its reasons. Loyalty to the mandate never outranks the duty to report.", wrong: { B: "Inverts the rule with an absolute — the Act requires termination plus reporting, not confidential note-taking.", C: "An authorised representative acts on the provider's mandate; it does not absorb provider status to launder a non-compliant placement.", D: "The representative's core job is keeping documentation AVAILABLE to the authorities; destruction is the exact opposite of the duty." }, strat: "Representative questions test escalation: when the principal goes rogue, the representative exits AND reports. Any option that keeps things quiet is bait.", trap: "absolute", bok: "Domain II, Competency C" },

  // F7 + F16 — retention pairing: logs vs AR documentation
  { id: "e-ddl-7", c: "ii-c", type: "recall", d: 3, stem: "A compliance analyst drafts the retention schedule for a high-risk AI provider and its EU authorised representative. Which pairing states the EU AI Act minimums correctly?", opts: [["Automatically generated logs: at least six months; documentation kept at the authorities' disposal by the authorised representative: ten years after the system is placed on the market", true], ["Logs: thirty days; authorised-representative documentation: five years", false], ["Logs: twelve months; authorised-representative documentation: twenty-five years", false], ["Logs: three years; authorised-representative documentation: two years", false]], why: "Article 19 sets a minimum six-month retention for automatically generated logs under the provider's control (longer where other law requires), and the authorised representative must keep the technical documentation and EU declaration of conformity available to the authorities for ten years after the system is placed on the market.", wrong: { B: "Both numbers are shrunk — thirty days is a plausible-sounding incident window, not the log minimum, and five years undershoots the documentation decade.", C: "Twelve months doubles the log minimum and twenty-five years has no basis in the Act — inflated figures read as safely conservative, which is the bait.", D: "Swaps magnitudes: logs do not need three years, and two years guts the ten-year documentation duty." }, strat: "Park the Act's numbers in pairs — logs six months, documentation ten years — and verify each half of a paired option independently; distractors swap magnitudes rather than invent exotic figures.", trap: "none", bok: "Domain II, Competency C" },

  // F9 + F12 — multi-authority enforcement vs GDPR one-stop-shop
  { id: "e-ddl-8", c: "ii-c", type: "distinction", d: 3, stem: "A governance lead who built her GDPR programme around the one-stop-shop mechanism assumes EU AI Act enforcement will likewise route through a single lead authority. The accurate correction is that the Act:", opts: [["distributes enforcement across several bodies at once — national market surveillance authorities policing product compliance, notified bodies performing third-party conformity assessments, and the AI Office and the European Artificial Intelligence Board operating at EU level", true], ["mirrors the GDPR: one lead market surveillance authority handles each company's EU-wide compliance", false], ["centralises all enforcement in the AI Office, whatever the system's risk tier", false], ["deputises notified bodies as the enforcement arm, with power to fine non-compliant providers directly", false]], why: "The AI Act's enforcement architecture is deliberately multi-authority, unlike the GDPR's lead-supervisory-authority model: market surveillance authorities are the national bodies monitoring and enforcing product compliance, notified bodies independently assess conformity, and the AI Office and AI Board sit at EU level.", wrong: { B: "Imports the GDPR's one-stop-shop into a product-safety regime that does not have one — anchoring on the familiar law is the designed error.", C: "The AI Office's supervisory remit centres on general-purpose AI models; national market surveillance authorities keep the product-enforcement load.", D: "Notified bodies assess conformity; they are not enforcers and levy no fines." }, strat: "Keep the institutions apart by function: surveil (market surveillance authority), assess (notified body), supervise GPAI and coordinate (AI Office). The AI Act multiplies watchdogs; the GDPR consolidates them.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F10 + F13 — AI Office vs European Artificial Intelligence Board
  { id: "e-ddl-9", c: "ii-c", type: "distinction", d: 2, stem: "A board paper keeps conflating two EU-level bodies. One sits within the Commission, supervises general-purpose AI model providers, facilitates codes of practice and can coordinate cross-border enforcement. The other is composed of member-state representatives, advises and assists the Commission, and promotes AI literacy and public-awareness tools. They are, respectively:", opts: [["the AI Office, and the European Artificial Intelligence Board", true], ["the European Artificial Intelligence Board, and the AI Office", false], ["the European Data Protection Supervisor, and the AI Office", false], ["a national market surveillance authority, and the European Data Protection Board", false]], why: "The AI Office, within the Commission, is the GPAI supervisor, code-of-practice facilitator and cross-border coordinator; the European Artificial Intelligence Board is the member-state body that advises and assists the Commission, including on AI literacy and public awareness.", wrong: { B: "A pure swap — it is there to catch anyone who cannot say which of the two actually supervises GPAI.", C: "The EDPS supervises EU institutions' data processing; it is not the GPAI supervisor.", D: "A market surveillance authority is national, not EU-level, and the EDPB belongs to the GDPR world, not the AI Act's advisory structure." }, strat: "Office = operational supervisor (GPAI, codes, coordination); Board = member states advising. Anchor one of the two and the swapped option collapses.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F11 — DPAs as MSAs for law enforcement / border / justice
  { id: "e-ddl-10", c: "ii-c", type: "role", d: 3, stem: "A member state is designating market surveillance authorities for high-risk AI operated by its police, border-control and judicial authorities. For these uses, the EU AI Act points the designation toward:", opts: [["the data protection supervisory authorities established under EU data-protection law, or other authorities offering equivalent independence guarantees", true], ["a notified body accredited for biometric systems", false], ["the AI Office, since fundamental rights are engaged", false], ["each police force's internal professional-standards unit", false]], why: "For high-risk AI used in law enforcement, border management and justice, member states designate as market surveillance authorities their data protection authorities — the GDPR/LED supervisory authorities — or other equivalent authorities, pairing the most rights-sensitive AI with independent rights regulators.", wrong: { B: "Notified bodies are third-party conformity assessors, not surveillance authorities — the perennial confusion the Act's institutional questions exploit.", C: "Fundamental-rights sensitivity does not move national enforcement to the AI Office, whose supervisory remit is general-purpose models.", D: "Internal police oversight lacks the independence the Act demands of a market surveillance authority for these uses." }, strat: "Law enforcement, borders, justice → think independence: the designated watchdog is the data protection authority, not a conformity assessor and not Brussels.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F14 — Art. 17 quality management system
  { id: "e-ddl-11", c: "ii-c", type: "recall", d: 2, stem: "An auditor asks a high-risk AI provider for the artefact that sets out, in written policies, procedures and instructions, its approach to regulatory compliance, data governance, risk management methodology, incident reporting and record keeping across the system's lifecycle. Under Article 17 of the EU AI Act, that artefact is the:", opts: [["quality management system", true], ["technical documentation", false], ["EU declaration of conformity", false], ["instructions for use", false]], why: "Article 17 requires providers to operate a documented quality management system — the policy-and-procedure backbone covering compliance strategy, data governance, risk management, post-market monitoring, incident reporting and record keeping across the lifecycle.", wrong: { B: "Technical documentation describes the SYSTEM — design, capabilities, performance — so authorities can assess conformity; it documents the product, not the provider's management processes.", C: "The declaration of conformity is a one-document attestation that the system meets the requirements, not a body of operating procedures.", D: "Instructions for use travel to deployers to enable safe operation; they are an output of the process, not the process." }, strat: "Product versus process: documentation that describes the system is technical documentation; documentation that describes how the provider runs itself is the quality management system.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F15 — Art. 20 corrective action (NOT item)
  { id: "e-ddl-12", c: "ii-c", type: "not", d: 3, stem: "Oristella, the provider of a high-risk tenant-vetting system sold across the EU, confirms that deployed instances no longer conform to the Act. Four response steps are proposed internally. Which one is NOT consistent with the provider's obligations?", opts: [["Refer the matter to the system's notified body and pause further action for up to thirty days while awaiting its corrective instructions", true], ["Immediately take corrective action — bring the system into conformity, or withdraw, disable or recall it", false], ["Inform the distributors, deployers, authorised representative and importers concerned of the non-conformity", false], ["Where the system presents a risk, immediately investigate the causes and inform the competent market surveillance authorities", false]], why: "Article 20 puts the corrective burden on the provider, immediately: fix, withdraw, disable or recall; tell the supply chain; and where risk exists, investigate and inform the authorities. A thirty-day pause awaiting notified-body instructions exists nowhere — conformity assessment bodies do not run incident response.", wrong: { B: "This is the core Article 20 duty — immediate corrective action spanning conformity fixes through recall.", C: "The information duty runs down the supply chain exactly this way, so each operator can act on its own obligations.", D: "Risk triggers immediate investigation plus notification of the market surveillance authorities — required, not optional." }, strat: "In NOT items about duties, hunt the option that swaps the responsible actor or inserts a waiting period; a statute that says 'immediately' does not tolerate a referral-and-wait step.", trap: "true-but-irrelevant", bok: "Domain II, Competency C" },

  // F17 + F18 — risk definition and the enumerated unacceptable tier
  { id: "e-ddl-13", c: "ii-c", type: "distinction", d: 3, stem: "An internal explainer on the EU AI Act's risk architecture offers four candidate sentences. Which one survives legal review?", opts: [["The Act defines risk as the combination of the probability of an occurrence of harm and the severity of that harm, and it marks the unacceptable tier not with a general definition but by listing prohibited practices in Article 5", true], ["The Act defines risk as the expected cost of remediating a failure, and defines unacceptable risk as any processing of biometric data", false], ["The Act scales risk with the number of users exposed, and prohibits any Annex III system whose documented risk score crosses the annex's threshold", false], ["The Act defines risk as probability combined with severity, and bans any practice whose quantified Article 5 risk score exceeds the statutory maximum", false]], why: "Article 3 defines risk as the combination of the probability of harm occurring and the severity of that harm, and the Act handles the unacceptable tier by enumeration: Article 5 lists the prohibited practices rather than defining unacceptable risk in the abstract.", wrong: { B: "Remediation cost is not the statutory definition, and the Act regulates — it does not blanket-ban — biometric processing.", C: "User count is not the definition, and Annex III contains use cases, not a scoring threshold; crossing an invented score does not prohibit anything.", D: "The first half is right, which is the trap: Article 5 contains no quantified risk score — the ban works by listed practices, not computed numbers." }, strat: "Half-true options die in their second clause: grade each claim in a two-claim sentence separately, and treat invented numeric precision (scores, thresholds) as a falsity marker.", trap: "premature", bok: "Domain II, Competency C" },

  // F19 — real-time RBI law-enforcement exceptions (multi-select)
  { id: "e-ddl-14", c: "ii-c", type: "recall", d: 3, multi: true, stem: "A member state's interior ministry lists five intended uses of real-time remote biometric identification in publicly accessible spaces by police. Under the EU AI Act's narrow law-enforcement exceptions, which three could — with the required authorisations and safeguards — be permissible? Select THREE.", opts: [["A targeted search for a six-year-old reported abducted that morning", true], ["Averting a specific and imminent threat to life identified in intelligence about a planned attack", true], ["Continuous scanning of a lawful demonstration to build a register of attendees", false], ["Locating a person suspected of a serious offence listed in the Act, such as trafficking in human beings, for criminal prosecution", true], ["Assembling a reusable facial-image database from public CCTV for unspecified future investigations", false]], why: "The default is prohibition; the carve-outs are targeted and enumerated: searches for victims of abduction, trafficking or missing persons; preventing a specific, substantial and imminent threat to life or a terrorist attack; and localising suspects of listed serious crimes.", wrong: { C: "Monitoring a lawful protest serves none of the enumerated aims and is the chilling-effect scenario the prohibition exists to prevent; 'continuous' is the opposite of targeted.", E: "Untargeted database-building is itself a prohibited practice — an open-ended surveillance asset cannot ride on exceptions written for specific, time-bound operations." }, strat: "The exceptions share a signature: a named person or a specific imminent event. Any use described as continuous, untargeted or for future purposes fails the signature on its face.", trap: "absolute", bok: "Domain II, Competency C" },

  // F21 — Annex I product manufacturer becomes provider
  { id: "e-ddl-15", c: "ii-c", type: "role", d: 3, stem: "Vexel Lifts manufactures passenger elevators, a product category covered by the Union harmonisation legislation listed in Annex I of the AI Act. Its new models embed an AI module — written by an outside contractor — that functions as the safety component deciding emergency braking, and the elevators ship under the Vexel name. For the module's high-risk obligations, the provider is:", opts: [["Vexel, because a product manufacturer that places a high-risk AI safety component on the market together with its product, under its own name or trademark, takes the provider role", true], ["the contractor, because provider status follows whoever actually wrote the code", false], ["each building operator that installs the elevators, as the party using the AI in the field", false], ["no one — AI embedded in Annex I products is governed solely by the sectoral product legislation, outside the AI Act", false]], why: "Annex I logic attaches provider duties to the product manufacturer: place the product with its AI safety component on the market under your own name and the AI Act treats you as the provider, whoever coded the module.", wrong: { B: "Authorship is irrelevant to provider status — the Act follows whose name the market sees, not whose engineers typed.", C: "Building operators are deployers at most; using a system never confers provider status by itself.", D: "Annex I products follow their sectoral conformity routes, but the AI Act's high-risk duties still attach — 'solely sectoral' is an invented exemption." }, strat: "For embedded AI, ask whose name is on the product that ships. Contractor, component-supplier and user options are decoys around the name-on-market rule.", trap: "true-but-irrelevant", bok: "Domain II, Competency C" },

  // F24 — oversight models answer autonomy
  { id: "e-ddl-16", c: "ii-c", type: "best", d: 2, stem: "Explaining the governance playbook, a risk officer says the human-in-the-loop, human-on-the-loop and human-out-of-the-loop options exist chiefly to manage one characteristic that separates AI from conventional software. Which characteristic?", opts: [["Autonomy — the system's capacity to operate and produce effects without step-by-step human direction", true], ["Opacity — the difficulty of inspecting the model's internal logic", false], ["Complexity — the scale of parameters and architecture involved", false], ["Statistical variance in the system's probabilistic outputs", false]], why: "Oversight models are dosage controls on autonomy: they set how much the system may do before a human intervenes. The more autonomous the operation, the more deliberate the choice among in-the-loop, on-the-loop and out-of-the-loop designs.", wrong: { B: "Opacity is answered by explainability and interpretability tooling, not by where the human sits in the action loop.", C: "Complexity drives testing and documentation burdens; it does not define who approves an action.", D: "Probabilistic variance motivates thresholds and monitoring, but the loop taxonomy is about control over autonomous action, not spread in outputs." }, strat: "Match the control to the characteristic it treats: loops treat autonomy, explanations treat opacity, monitoring treats drift. Synonym options come from the wrong pairing.", trap: "synonym-bait", bok: "Domain II, Competency C" },

  // F25 — three lines of defense
  { id: "e-ddl-17", c: "iv-a", type: "role", d: 2, stem: "At Merimont Bank, the model-owning business line manages its AI risks day to day, and a central risk-and-compliance function sets policy and challenges the line's decisions. The board now wants independent assurance that the whole arrangement actually works, including validation of the controls. In the three-lines-of-defense model, that assurance belongs to:", opts: [["internal audit, acting as the third line", true], ["the model-owning business line, as the first line closest to the risk", false], ["the central risk-and-compliance function, as the second line", false], ["the bank's external market regulator, as the ultimate overseer", false]], why: "First line owns and manages risk; second line sets frameworks and challenges; the third line — internal audit — independently assures and validates that the first two actually function.", wrong: { B: "The first line cannot independently assure its own risk-taking — that is the conflict the model exists to prevent.", C: "The second line designed the framework being assessed; reviewing its own architecture is oversight, not independent assurance.", D: "Regulators supervise from outside the organisation; the three lines are internal. Importing the regulator mistakes external enforcement for the third line." }, strat: "Map the verbs: own/manage = first line, set/challenge = second, independently assure/validate = third. Inside the organisation, 'who checks the checkers' is always internal audit.", trap: "synonym-bait", bok: "Domain IV, Competency A" },

  // F26 — what an AI audit is and is not (NOT item)
  { id: "e-ddl-18", c: "i-a", type: "not", d: 3, stem: "Pitching an AI audit of the company's deployed models, a director makes four claims about what the exercise involves or achieves. Which claim is NOT accurate?", opts: [["Completing the audit itself certifies the company under ISO/IEC 42001 and stands in for any conformity assessment the law requires", true], ["It systematically examines the systems against applicable laws, standards and internal policies", false], ["It maps where the organisation's AI risks actually sit", false], ["It can be conducted against recognised criteria by an independent party and documented as assurance evidence", false]], why: "An AI audit is a systematic check of systems against laws, standards and internal policies that maps risk — valuable assurance, but not a certificate. ISO/IEC 42001 certification is issued through an accredited certification process, and statutory conformity assessments run on their own legal track; an audit substitutes for neither. Nor is it a voluntary self-assessment — criteria and rigor distinguish it.", wrong: { B: "That is the definitional core of an AI audit.", C: "Risk mapping is exactly what the systematic examination yields.", D: "Independence, criteria and documentation are what elevate an audit above self-assessment." }, strat: "Audit items test boundaries: an audit informs and evidences; it does not certify or legally clear. Watch for 'itself' and 'stands in for' — substitution claims are the planted falsehood.", trap: "absolute", bok: "Domain I, Competency A" },

  // F27 — HITL / HOTL / HOOTL mapping
  { id: "e-ddl-19", c: "iv-c", type: "distinction", d: 2, stem: "Corvina Health runs three AI deployments: (1) a dosing recommender whose every suggestion a pharmacist must approve before it reaches the ward; (2) a bed-allocation engine that acts on its own while a duty manager watches the dashboard and can intervene or override; (3) an after-hours claims bot that settles small claims end to end with no human involved. The correct oversight labels, in order, are:", opts: [["(1) human-in-the-loop; (2) human-on-the-loop; (3) human-out-of-the-loop", true], ["(1) human-on-the-loop; (2) human-in-the-loop; (3) human-out-of-the-loop", false], ["(1) human-in-the-loop; (2) human-out-of-the-loop; (3) human-on-the-loop", false], ["(1), (2) and (3) are all human-in-the-loop, because humans designed and can decommission each system", false]], why: "Approving each recommendation before it takes effect is human-in-the-loop; monitoring with the ability to intervene while the system acts is human-on-the-loop; no human involvement in operation is human-out-of-the-loop.", wrong: { B: "Swaps the first two: a gate on every individual decision is IN the loop; supervision of an autonomous flow is ON it.", C: "Calls an actively supervised engine out-of-the-loop and an unattended bot on-the-loop — both labels contradict the stated facts.", D: "Design-time involvement is not operational oversight; by that absolute, no system could ever be out of the loop." }, strat: "Ask where the human sits relative to each individual decision: before it (in), above it (on), nowhere (out). Design-time and governance involvement are off the taxonomy's axis.", trap: "synonym-bait", bok: "Domain IV, Competency C" },

  // F60 — extraterritorial reach via output used in the Union
  { id: "e-ddl-20", c: "ii-c", type: "best", d: 3, stem: "Andara Metrics, a Sao Paulo analytics firm with no EU establishment, runs its underwriting-risk AI entirely on Brazilian infrastructure and sells the system's risk scores to insurers in Spain, which use them to price policies for Spanish customers. Andara's counsel advises that the EU AI Act cannot reach a company with no presence in the Union. That advice is:", opts: [["wrong — the Act expressly reaches third-country operators where the output produced by the AI system is used in the Union", true], ["right — the Act's territorial scope is limited to operators established in a member state", false], ["right as to Andara — only the Spanish insurers, as the EU-facing deployers, can have any exposure under the Act", false], ["wrong — but only because Brazil lacks an adequacy decision covering algorithmic outputs", false]], why: "The AI Act's extraterritorial hooks include output use: providers and deployers located in third countries fall within scope where the system's output is used in the Union. Spanish insurers pricing Spanish policies with Andara's scores is exactly that hook.", wrong: { B: "The establishment-only reading erases the Act's extraterritorial provisions — placing on the EU market and output-used-in-the-Union both reach outsiders.", C: "Partially true and therefore dangerous: the insurers do carry deployer duties, but their exposure does not extinguish Andara's own — scope is not a single seat.", D: "Adequacy decisions belong to GDPR transfer law; they play no role in the AI Act's territorial scope." }, strat: "Scope questions have three hooks — established in the EU, placing on the EU market, output used in the EU. Run all three before accepting any 'no presence, no problem' conclusion.", trap: "too-narrow", bok: "Domain II, Competency C" },

  // ───────── B. Other laws & frameworks ─────────

  // F28 — pseudonymised data stays personal data
  { id: "e-ddl-21", c: "ii-a", type: "best", d: 2, stem: "Milvik Credit replaces customer names and account numbers with random tokens before using the records to train a scoring model; a separately stored key can re-link every token to its customer. The data lead announces that the GDPR no longer applies to the training set. The correct assessment is that the set:", opts: [["is pseudonymised, not anonymised — while the re-linking key exists the records remain personal data, squarely within the GDPR", true], ["is out of scope, because replacing direct identifiers is what the GDPR means by anonymisation", false], ["is out of scope, because the GDPR governs raw identifiers such as names, not substitute codes", false], ["remains in scope, but only because trained models are themselves always personal data", false]], why: "Pseudonymisation keeps data personal: identification remains possible with additional information — here, the stored key — so the GDPR continues to apply. Only anonymisation, where re-identification is no longer reasonably possible, takes data out of scope.", wrong: { B: "Token substitution with a surviving key is the GDPR's textbook definition of pseudonymisation, not anonymisation.", C: "The GDPR turns on identifiability, not on the format of the identifier — a code that maps back to a person is personal data.", D: "Reaches the right conclusion through an invented rule: the set is in scope because of the key, not because models are categorically personal data." }, strat: "One question decides these items: can anyone, with reasonably available means, get back to the individual? A stored key means yes — and yes means GDPR.", trap: "synonym-bait", bok: "Domain II, Competency A" },

  // F29 — erasure vs trained model weights
  { id: "e-ddl-22", c: "ii-a", type: "best", d: 3, stem: "A former user of Lintra's conversational assistant exercises her right to erasure. Lintra deletes her account and chat history, but her data was part of a completed training run for the production model. The privacy engineer warns leadership that the difficult part is still ahead. That difficulty is best described as:", opts: [["there is no established, reliable technique for excising one individual's contribution from trained model weights — the machine-unlearning problem — so honouring erasure against the model itself is technically fraught", true], ["a non-issue, because the right to erasure lapses once data has been absorbed into training", false], ["jurisdictional — model-level erasure requests must be referred to the AI Office for adjudication", false], ["procedural — the real work is verifying the requester's identity before any deletion", false]], why: "Erasure still applies, but a trained model does not store records that can be plucked out: a person's contribution is diffused through the weights, and machine unlearning remains unsolved at production scale. The gap between a live legal right and an undefined technical operation is the hard part.", wrong: { B: "The right does not expire at training time — asserting it does converts an open compliance problem into an imaginary exemption.", C: "No such referral mechanism exists; the AI Office supervises general-purpose model providers under the AI Act, it does not adjudicate GDPR requests.", D: "Identity verification is a routine step the scenario has already passed; calling it the hard part ignores the model entirely." }, strat: "When a data-subject right meets a trained model, the tested fact is nearly always the weights problem: the right survives, the technique lags.", trap: "true-but-irrelevant", bok: "Domain II, Competency A" },

  // F31 — transfer safeguards: SCCs and BCRs
  { id: "e-ddl-23", c: "ii-a", type: "recall", d: 2, stem: "Orvantis GmbH wants to send EU employee records to its engineering hub in a third country with no adequacy decision, to fine-tune an internal assistant. Which pair of instruments is designed to serve as appropriate safeguards for that transfer?", opts: [["Standard contractual clauses, or binding corporate rules for intra-group transfers", true], ["A record of processing activities and a data protection impact assessment", false], ["A legitimate-interests assessment and an updated cookie policy", false], ["An ISO/IEC 42001 certificate and a published model card", false]], why: "Absent adequacy, GDPR transfers ride on appropriate safeguards — and the named workhorses are standard contractual clauses and, for corporate groups, binding corporate rules.", wrong: { B: "Both are accountability instruments — they document and assess processing but authorise no transfer; mistaking records for safeguards is the planted confusion.", C: "A legitimate-interests assessment addresses lawful basis and a cookie policy addresses ePrivacy transparency; neither moves data across borders lawfully.", D: "Management-system certification and model documentation evidence AI governance maturity, not Chapter V transfer compliance." }, strat: "Sort GDPR paperwork into jobs — lawful basis, accountability records, transfer mechanisms — and answer transfer questions only from the third pile: SCCs, BCRs, adequacy.", trap: "true-but-irrelevant", bok: "Domain II, Competency A" },

  // F32 — controller vs processor (with the reuse twist)
  { id: "e-ddl-24", c: "ii-a", type: "role", d: 3, stem: "Quellan HR, a SaaS vendor, hosts and runs an attrition-prediction service strictly on each client employer's documented instructions; the employers decide what is predicted, about whose data, and how results are used. Quellan's product chief now proposes quietly reusing the pooled client data to improve the product for all customers. Before any such reuse happens, the GDPR roles are:", opts: [["each employer is a controller — it determines the purposes and means — and Quellan is a processor acting on its behalf; the proposed self-interested reuse would make Quellan a controller for that new processing", true], ["Quellan is the controller, because the party physically running the computation controls the data", false], ["both are automatically joint controllers whenever machine learning is involved", false], ["the employees are the controllers, since the personal data is about them", false]], why: "Controllership follows decision-making power over purposes and means, which the stem places with the employers; Quellan processes on documented instructions. The reuse plan matters because a processor that starts processing for its own purposes becomes a controller for that processing.", wrong: { B: "Physical computation is execution of the means, not determination of purposes — the hosting party on instructions is the classic processor.", C: "Joint controllership requires jointly determined purposes and means; no machine-learning-automatic rule exists.", D: "Data subjects hold rights over their data; being described by data has never conferred controllership." }, strat: "Ask who decides WHY and HOW, not who touches the data. Then watch the twist: self-directed reuse flips a processor into a controller for that use.", trap: "synonym-bait", bok: "Domain II, Competency A" },

  // F33 — records serve transparency + accountability
  { id: "e-ddl-25", c: "ii-a", type: "recall", d: 2, stem: "Beyond satisfying documentation requirements, maintaining data inventories, data-flow diagrams and records of processing activities primarily operationalises which pair of privacy principles?", opts: [["Transparency and accountability", true], ["Data minimisation and storage limitation", false], ["Lawfulness and consent", false], ["Integrity and confidentiality", false]], why: "Inventories, flow diagrams and processing records make the organisation able to SHOW what it does with personal data — visibility outward (transparency) and demonstrable responsibility inward (accountability).", wrong: { B: "Minimisation and storage limitation discipline how much data exists and for how long; records describe processing rather than shrink it.", C: "Lawful basis and consent govern whether processing may happen at all — records evidence the answer but are not the principles at work.", D: "Integrity and confidentiality are delivered by security controls, not by documentation of flows." }, strat: "Records answer 'can you show what you do?' — that phrasing is the transparency-and-accountability fingerprint on exam items.", trap: "synonym-bait", bok: "Domain II, Competency A" },

  // F34 — FTC Act Section 5 facts (multi-select)
  { id: "e-ddl-26", c: "ii-b", type: "recall", d: 3, multi: true, stem: "An in-house seminar tests counsel on the US FTC's consumer-protection authority as it applies to AI marketing and deployment. Which three statements are accurate? Select THREE.", opts: [["Genuine non-profit organisations, banks and common carriers fall squarely within Section 5's reach", false], ["Section 5 of the FTC Act, the source of the unfair-or-deceptive-practices authority, was enacted in 1914", true], ["The unfairness standard was codified in 1994 at 15 U.S.C. § 45(n)", true], ["The FTC is the exclusive federal enforcer of the FCRA and ECOA", false], ["The FTC holds both rulemaking and enforcement authority under COPPA", true]], why: "Section 5 dates to 1914; Congress codified the unfairness standard in 1994 at 15 U.S.C. § 45(n); and COPPA is the FTC's own domain for both rulemaking and enforcement.", wrong: { A: "The FTC Act reaches entities organised for profit — genuine non-profits sit outside it, and banks and common carriers are carved out to other regulators.", D: "FCRA and ECOA enforcement is shared with other federal agencies; 'exclusive' overstates a shared docket — COPPA, not these, is where the FTC owns the field." }, strat: "For agency questions, memorise reach and exceptions as one unit: for-profits yes; non-profits, banks, common carriers no; shared statutes versus owned statutes (COPPA).", trap: "absolute", bok: "Domain II, Competency B" },

  // F35 — codified unfairness test: intent is NOT an element
  { id: "e-ddl-27", c: "ii-b", type: "not", d: 3, stem: "Preparing an unfair-practice theory against a subscription app whose AI-driven cancellation flow traps users, an associate lists four things she intends to prove. Which listed element is NOT part of the codified unfairness test?", opts: [["That the company intended to mislead its users", true], ["That the practice causes or is likely to cause substantial injury to consumers", false], ["That consumers cannot reasonably avoid the injury themselves", false], ["That the injury is not outweighed by countervailing benefits to consumers or competition", false]], why: "The codified test has exactly three prongs — substantial injury, not reasonably avoidable by consumers, not outweighed by countervailing benefits. Intent and deception are no part of it: unfairness is a separate theory from deception, and neither requires proving the company meant to mislead.", wrong: { B: "Prong one of the codified standard — substantial injury.", C: "Prong two — the injury must not be one consumers could reasonably sidestep themselves.", D: "Prong three — the cost-benefit backstop protecting beneficial practices." }, strat: "Keep unfairness and deception in separate boxes: deception concerns misleading representations, unfairness is the three-prong injury test — and intent appears in neither as an element.", trap: "synonym-bait", bok: "Domain II, Competency B" },

  // F36 + F59 — ADEA + EEOC-urged practice
  { id: "e-ddl-28", c: "ii-b", type: "best", d: 3, stem: "Halbrook Freight notices its resume-ranking AI surfaces almost no candidates over fifty for driver-trainer roles. HR asks which federal statute most directly governs this exposure, and what practice the enforcing agency urges on employers that use such tools. The best pairing is:", opts: [["the Age Discrimination in Employment Act, enforced by the EEOC — which urges regular bias audits and testing of the hiring tool's outcomes", true], ["Title VII, enforced by the EEOC — which urges discontinuing every form of algorithmic screening", false], ["the Americans with Disabilities Act, enforced by the FTC — which urges keeping the tool's use confidential from applicants", false], ["the Fair Credit Reporting Act, enforced by the EEOC — which urges removing human review so outcomes stay consistent", false]], why: "Age is the protected trait, so the ADEA — protecting workers aged forty and over and enforced by the EEOC — governs; and the agency's urged practice for AI hiring tools is routine bias auditing and testing, not concealment or abandonment.", wrong: { B: "Title VII covers race, color, religion, sex and national origin — age lives in the ADEA; and 'discontinuing every form' is an absolute no agency urges.", C: "Wrong statute (disability), wrong agency (the EEOC, not the FTC, enforces the ADA's employment title), and concealing AI use inverts the transparency regulators expect.", D: "The FCRA governs consumer reports used in hiring, not age discrimination, and stripping human oversight is the opposite of recommended practice." }, strat: "Decompose pairing options into statute → agency → practice and grade each link; a single broken link kills the option, and most distractors break two.", trap: "synonym-bait", bok: "Domain II, Competency B" },

  // F37 — disparate impact needs no intent
  { id: "e-ddl-29", c: "ii-b", type: "distinction", d: 3, stem: "Tenant applicants challenge Keystone Property's screening algorithm: a facially neutral rule weighting depth of rental history disproportionately excludes members of a protected class. Keystone's CEO responds that the company never intended to discriminate and that this ends the matter. The most accurate statement of US discrimination doctrine is:", opts: [["under disparate impact, a facially neutral practice that disproportionately harms a protected group can create liability with no showing of intent — intent is the hallmark of disparate treatment, a different theory", true], ["the CEO is right — every US discrimination theory requires proof of discriminatory purpose", false], ["using an algorithm converts the claim into disparate treatment, because the company chose the model deliberately", false], ["intent is irrelevant under both theories, so the CEO's statement is wrong twice over", false]], why: "Disparate impact asks what the neutral practice DOES, not what its author meant: disproportionate harm to a protected group can suffice without intent. Intent belongs to disparate treatment, the deliberate-discrimination theory.", wrong: { B: "An absolute that erases disparate impact from the law — the doctrine exists precisely for unintended, facially neutral harm.", C: "Deliberately choosing a tool is not deliberately discriminating through it; treatment needs intent aimed at the protected trait.", D: "Overcorrects: intent is irrelevant to impact but is the defining element of treatment." }, strat: "File the pair as what-it-does versus why-they-did-it. Any option making intent necessary everywhere, or nowhere, is mechanically wrong.", trap: "absolute", bok: "Domain II, Competency B" },

  // F40 — FIPs: enforcement/redress mapping
  { id: "e-ddl-30", c: "ii-b", type: "best", d: 2, stem: "Vanterra Fit's app discloses its data practices clearly, collects only what the service needs, and lets members view and correct their records. But when members report misuse of their data, there is no complaints channel, no internal remediation process and no avenue of recourse at all. Which Fair Information Practice is the programme missing?", opts: [["Enforcement/redress — mechanisms to ensure compliance and remedy violations", true], ["Notice/awareness — informing individuals about collection practices", false], ["Collection limitation — gathering no more data than needed", false], ["Access/participation — letting individuals view and correct their data", false]], why: "The Fair Information Practices end with teeth: enforcement and redress require working mechanisms — complaint channels, remediation, recourse — so the other principles are not promises on paper. The stem satisfies notice, limitation and access by its own terms, leaving only redress unmet.", wrong: { B: "The stem grants clear disclosure, so notice is satisfied — choosing it means overriding the scenario's explicit facts.", C: "Collection is described as minimal; the defect sits downstream of collection.", D: "View-and-correct rights are expressly provided; what is missing is remedy when things go wrong, not access." }, strat: "FIP mapping stems often satisfy three principles on purpose; inventory what the facts already grant and the missing principle names itself.", trap: "none", bok: "Domain II, Competency B" },

  // F41 — DSA scope
  { id: "e-ddl-31", c: "ii-d", type: "best", d: 2, stem: "Four executives each claim the EU Digital Services Act is their company's problem. Whose claim matches the DSA's actual scope?", opts: [["The operator of an online marketplace connecting third-party sellers with consumers", true], ["The developer of a diagnostic AI sold to hospital radiology departments", false], ["A manufacturer of smart thermostats sold at retail", false], ["A vendor of internal HR software that hosts no third-party or user content", false]], why: "The DSA regulates online intermediaries and platforms — marketplaces, social media, app stores and the like. A marketplace intermediating between third-party sellers and consumers is its paradigm addressee.", wrong: { B: "A high-risk clinical AI points to the AI Act and medical-device law; the DSA governs intermediary services, not AI providers as such.", C: "Device manufacturing is product-law territory; no intermediation of third-party content or commerce occurs.", D: "Enterprise software without third-party content performs no intermediary function, which is the DSA's trigger." }, strat: "The DSA's scope question is 'do you intermediate other people's content or commerce online?' — not 'are you digital?'", trap: "true-but-irrelevant", bok: "Domain II, Competency D" },

  // F42 + F43 — DSA ad + recommender transparency (multi-select)
  { id: "e-ddl-32", c: "ii-d", type: "best", d: 3, multi: true, stem: "Paloma Social, a large EU platform, is scoping its Digital Services Act transparency work for advertising and its content feed. Which three obligations belong on its list? Select THREE.", opts: [["Enable users to see the main parameters used to determine why a particular advertisement is shown to them", true], ["Publish the full training datasets behind any machine learning used to rank content", false], ["Tell users whether profiling was used to select the advertisement they are being shown", true], ["Disclose the main parameters of its recommender system — how it shapes what each user sees", true], ["Report the revenue earned from each advertisement displayed", false]], why: "DSA ad transparency gives users the ad's main targeting parameters and whether profiling selected it; recommender transparency requires disclosing the system's main parameters — how it determines what users see.", wrong: { B: "The DSA requires parameter-level transparency, not dataset publication; demanding training corpora reads like transparency but appears nowhere in the duty.", E: "Per-ad revenue is commercially confidential detail the DSA never requires — plausible-sounding, invented." }, strat: "The DSA's transparency currency is 'main parameters'. Options promising deeper artefacts — datasets, architectures, revenue — overshoot the statute and are planted.", trap: "true-but-irrelevant", bok: "Domain II, Competency D" },

  // F44 + F45 — HUDERAF origin and proportionality
  { id: "e-ddl-33", c: "ii-d", type: "recall", d: 3, stem: "A ministry adviser cites HUDERAF — an assurance framework addressing AI's impacts on human rights, democracy and the rule of law, under which the depth of risk management and stakeholder involvement scales with the likelihood and the extent of adverse impacts on human rights. Which statement about the framework's origin is correct?", opts: [["It was produced for the Council of Europe by its ad hoc committee on AI (CAHAI) — a body spanning forty-six member states that could advise but not itself legislate", true], ["It is an OECD instrument, binding on all adherent countries", false], ["It was issued by the European Commission as implementing guidance for the EU AI Act", false], ["It was adopted by the European Data Protection Board as GDPR interpretation", false]], why: "HUDERAF came out of the Council of Europe's ad hoc committee on AI, CAHAI. Two anchors matter: the Council of Europe is the forty-six-state human-rights organisation distinct from the EU, and CAHAI advised — it had no power to legislate. Its proportionality principle scales assurance effort with the likelihood and severity of adverse human-rights impacts, not with compute, turnover or member-state counts.", wrong: { B: "Wrong body and doubly wrong on force — OECD AI instruments are non-binding principles, and HUDERAF is not one of them.", C: "Confuses the Council of Europe with the EU institutions; HUDERAF is not AI Act guidance.", D: "The EDPB interprets EU data-protection law; a human-rights assurance framework for AI is outside both its remit and its authorship." }, strat: "Keep a who-wrote-it ledger: Council of Europe/CAHAI → HUDERAF. Distractors always offer the better-known EU and OECD bodies; fame is not authorship.", trap: "synonym-bait", bok: "Domain II, Competency D" },

  // F46 + F47 + F48 — Canada / Singapore / Japan instruments
  { id: "e-ddl-34", c: "ii-d", type: "distinction", d: 3, stem: "A comparative-law slide pairs three jurisdictions with their signature AI-governance instruments. Which option gets all three right?", opts: [["Canada — a 2023 voluntary code of conduct aimed specifically at advanced generative AI; Singapore — Asia's first national AI governance framework, the Model AI Governance Framework of 2019; Japan — a promotion-oriented basic law on AI that is non-binding and carries no penalties", true], ["Canada — a binding 2023 licensing statute for generative AI; Singapore — Asia's first national AI governance framework (2019); Japan — a non-binding, promotion-oriented basic law", false], ["Canada — a 2023 voluntary code for advanced generative AI; Singapore — Asia's first binding national AI statute; Japan — a penalty-backed risk law modelled on the EU's", false], ["Canada — a voluntary code limited to facial recognition; Singapore — Asia's second national framework, following Japan's; Japan — a binding promotion law with administrative fines", false]], why: "Canada's 2023 instrument is a voluntary code of conduct for advanced generative AI systems; Singapore's 2019 Model AI Governance Framework was Asia's first national AI governance framework; and Japan's AI law takes a promotion-oriented, non-binding basic-law approach without penalties — a deliberate contrast with the EU's binding, risk-based regulation.", wrong: { B: "Two-thirds right: the Singapore and Japan entries hold, but Canada's code is voluntary — 'binding licensing statute' sinks the option.", C: "Only Canada survives; Singapore's framework is guidance, not a binding statute, and Japan enacted promotion, not penalties.", D: "Nothing survives: Canada's code targets advanced generative AI broadly, Singapore preceded rather than followed, and 'binding with fines' contradicts Japan's approach." }, strat: "In all-three-must-match options, hunt the single falsified element in each line rather than re-reading whole options; one broken pair eliminates the letter.", trap: "too-narrow", bok: "Domain II, Competency D" },

  // F49 — regulatory-approach taxonomy
  { id: "e-ddl-35", c: "ii-d", type: "distinction", d: 2, stem: "Three jurisdictions take different roads on AI. Volaria enacts a single omnibus statute governing AI across every sector. Merchend leaves its sectoral banking, health and employment statutes in place and amends each one to address AI. Caldora publishes non-mandatory industry pledges and invites firms to self-certify. The matching taxonomy is:", opts: [["Volaria — comprehensive legislation; Merchend — amending existing laws; Caldora — voluntary self-regulation", true], ["Volaria — amending existing laws; Merchend — comprehensive legislation; Caldora — voluntary self-regulation", false], ["Volaria — comprehensive legislation; Merchend — voluntary self-regulation; Caldora — amending existing laws", false], ["All three are forms of binding risk-based regulation, differing only in drafting style", false]], why: "One omnibus statute is the comprehensive approach; piecemeal AI amendments to standing sectoral laws is the amending-existing-law approach; non-mandatory pledges with self-certification is the voluntary route.", wrong: { B: "Swaps the first two labels against the stated facts — Volaria wrote one statute, Merchend wrote none.", C: "Calls pledges 'amendment' and amendments 'voluntary'; neither label matches its described jurisdiction.", D: "An absolute that erases the taxonomy — voluntary pledges bind no one, so 'all binding' is false on its face." }, strat: "Taxonomy items are matching drills: label each described jurisdiction yourself before reading the options, then eliminate every option that contradicts even one of your labels.", trap: "synonym-bait", bok: "Domain II, Competency D" },

  // F50 — the patchwork problem + strictest-standard strategy
  { id: "e-ddl-36", c: "ii-b", type: "recall", d: 3, stem: "Brimworth Insurance runs one underwriting AI across nine US states and three other countries whose AI rules conflict on notice, audit and opt-out requirements. Its general counsel describes both the landscape and the standard corporate response to it. The accurate description is:", opts: [["a regulatory patchwork — overlapping, inconsistent obligations across jurisdictions — most commonly managed by building the compliance programme to the strictest applicable standard", true], ["federal preemption — national law displaces the conflicting state rules, so a single federal standard controls", false], ["the Brussels effect — meaning the company need only comply with EU law and the rest follows", false], ["regulatory arbitrage — best answered by relocating operations to the lightest-touch jurisdiction available", false]], why: "Conflicting multi-jurisdiction AI obligations are the patchwork problem, and the prevailing corporate strategy is to engineer one programme to the strictest applicable standard so every lesser regime is satisfied by construction.", wrong: { B: "No omnibus federal AI statute preempts the field; asserting preemption wishes the conflict away rather than describing it.", C: "The Brussels effect describes EU rules spreading de facto — it is not a compliance strategy and does not nullify US state law.", D: "Chasing the lightest regime optimises cost over obligation and fails the moment a strict jurisdiction's customers or data are touched." }, strat: "Fragmented-rules scenarios pair a diagnosis with a remedy: patchwork → strictest-standard build. Options offering relocation or a single magic regime are planted economics traps.", trap: "wrong-economics", bok: "Domain II, Competency B" },

  // F51 — Calo: objective privacy harm
  { id: "e-ddl-37", c: "ii-d", type: "distinction", d: 3, stem: "Months after Cliffbrook Fitness quietly passed members' workout and location logs to a debt-collection partner, members begin receiving collection calls timed to their gym visits — a use of their data none of them anticipated. Under Ryan Calo's dichotomy of privacy harms, the members have suffered:", opts: [["objective harm — the forced or unanticipated use of their personal data, an external harm that has actually occurred", true], ["subjective harm — the internal perception of unwanted observation, such as a chilling sense of being watched", false], ["no cognisable privacy harm, because members voluntarily shared the data with the gym in the first place", false], ["aggregation harm — the re-identification that occurs when de-identified datasets are combined", false]], why: "Calo splits privacy harm into subjective — the internal experience of unwanted observation — and objective — the external, actual forced or unanticipated use of a person's data. Collection calls timed to gym visits are data put to unanticipated use: objective.", wrong: { B: "Subjective harm would fit members who merely felt watched; here the data was actually used against them, which crosses into the objective category.", C: "An absolute consent fallacy — sharing with the gym never anticipated or authorised a debt collector's use.", D: "A real concept from a different taxonomy: nothing here involves combining de-identified datasets." }, strat: "For Calo items ask one question: did something actually happen with the data (objective), or does the person experience being observed (subjective)? Use versus perception decides it.", trap: "synonym-bait", bok: "Domain II, Competency D" },

  // F52 — MITRE PANOPTIC
  { id: "e-ddl-38", c: "ii-d", type: "recall", d: 2, stem: "A security architect who relies on MITRE ATT&CK to enumerate adversary techniques asks for the equivalent catalogue for privacy threats. The closest match is:", opts: [["MITRE PANOPTIC, a privacy-threat taxonomy positioned as the privacy analogue of ATT&CK", true], ["the NIST AI RMF Map function", false], ["Calo's subjective/objective harm dichotomy", false], ["ISO/IEC 27701 certification", false]], why: "PANOPTIC is MITRE's privacy-threat taxonomy, deliberately framed as doing for privacy threats what ATT&CK does for adversary techniques.", wrong: { B: "Map establishes context and identifies risks inside a risk-management framework; it is a process function, not a threat catalogue.", C: "A two-category harm dichotomy — analytically useful, but not an enumerated taxonomy of threat activity.", D: "A certifiable privacy information management standard; certification schemes are not threat enumerations." }, strat: "Match artefact types: catalogue to catalogue. When the stem asks for an ATT&CK-like enumeration, frameworks, dichotomies and certifications are category errors.", trap: "true-but-irrelevant", bok: "Domain II, Competency D" },

  // F53 — spillover (vs persistence, repurposing)
  { id: "e-ddl-39", c: "ii-a", type: "distinction", d: 3, stem: "Dorsey Home's video-doorbell assistant, purchased by homeowners, routinely captures audio, faces and gait data of couriers, neighbours and passers-by who never chose or engaged with the product. In the privacy risk register this is primarily an instance of:", opts: [["spillover — personal data about non-users collected incidentally by a system aimed at its users", true], ["persistence — personal data continuing to exist beyond the data subject's engagement with the service", false], ["repurposing — collected data being put to a new secondary use", false], ["data localisation — data being stored in the wrong jurisdiction", false]], why: "Spillover names exactly this pattern: the system's sensing sweeps in people outside the user relationship. The passers-by never engaged, so the risk is about WHO is captured — not how long data is kept or what new use it is put to.", wrong: { B: "Persistence is a time-axis risk — data outliving engagement, demanding retention schedules; the passers-by never engaged at all.", C: "No second use appears in the facts; the defect sits at collection, not downstream.", D: "Nothing in the stem concerns storage geography." }, strat: "Give each data-risk term an axis: spillover = who, persistence = how long, repurposing = what for. Match the stem's axis before touching the options.", trap: "synonym-bait", bok: "Domain II, Competency A" },

  // F54 — aggregation re-identification (Solove)
  { id: "e-ddl-40", c: "i-a", type: "best", d: 2, stem: "A transit authority publishes an anonymised trip log; a hospital separately publishes anonymised visit-timing data. A data broker joins the two releases on timestamps and station proximity and begins re-identifying individual patients. This illustrates which privacy harm?", opts: [["Aggregation — combining individually de-identified datasets until individuals become identifiable again", true], ["Spillover — incidental collection of data about non-users", false], ["Membership inference — probing a model to learn whether a record was in its training data", false], ["Data loss — destruction or unavailability of personal data", false]], why: "Each release was defensible alone; identifiability emerged from the combination. That is aggregation harm — the join, not either dataset, produces the re-identification.", wrong: { B: "Everyone in these datasets was a rider or patient of the publishing bodies; the problem is linkage, not incidental capture of outsiders.", C: "No model is being probed — membership inference is an attack on trained models, not on published tables.", D: "The data is all too available; loss is the opposite failure mode." }, strat: "When two harmless releases become harmful only in combination, the tested term is aggregation; distractors will name attacks or collection problems that need facts the stem lacks.", trap: "synonym-bait", bok: "Domain I, Competency A" },

  // F55 — misinformation / disinformation / deepfake / echo chamber
  { id: "e-ddl-41", c: "i-a", type: "distinction", d: 3, stem: "Four incidents mark Calder City's election week: (1) a neighbourhood page shares a wrong polling-station map it genuinely believed accurate; (2) a political operative circulates the same wrong map knowing it is false; (3) a synthetic video shows a candidate conceding a race she never conceded; (4) a video app's recommender keeps feeding each user only outrage content consistent with views they already hold. The correct labels, in order, are:", opts: [["misinformation; disinformation; deepfake; echo chamber", true], ["disinformation; misinformation; deepfake; echo chamber", false], ["misinformation; disinformation; echo chamber; deepfake", false], ["deepfake; disinformation; misinformation; echo chamber", false]], why: "Intent is the hinge between the first two: false content shared without intent to mislead is misinformation; the same content shared knowingly is disinformation. Synthetic fabricated media is a deepfake, and a recommender feeding only belief-consistent content builds an echo chamber.", wrong: { B: "Swaps the intent hinge — the believing neighbourhood page lacks intent, the knowing operative has it.", C: "Mislabels the last pair: the fabricated synthetic video is the deepfake; the feed loop is the echo chamber.", D: "Calls an honestly mistaken map a deepfake; nothing in incident (1) is synthetic media." }, strat: "Decide intent first (mis- versus dis-), then medium (synthetic = deepfake), then mechanism (feedback loop = echo chamber). Three axes, three clean cuts.", trap: "synonym-bait", bok: "Domain I, Competency A" },

  // F56 — profiling for political manipulation
  { id: "e-ddl-42", c: "i-a", type: "best", d: 2, stem: "Investigators find that Atlas Persuasion harvested millions of quiz-takers' social-graph data, built psychometric profiles, and sold political campaigns the ability to micro-target emotionally tailored ads at persuadable voter segments. In AI-governance harm terms, this pattern is the canonical case of:", opts: [["profiling deployed for targeted political manipulation — a harm operating at group and societal scale", true], ["an individual data-breach harm confined to the quiz-takers whose accounts were accessed", false], ["an organisational harm, namely reputational damage to the platform that allowed the harvesting", false], ["an ecosystem harm, since election infrastructure is a shared resource", false]], why: "The signature is profiling — psychometric classification of people — put to work manipulating political behaviour, and the harm lands on groups and on society's democratic processes, not merely on the profiled individuals.", wrong: { B: "Too narrow: framing it as a breach of some accounts misses the manipulation of electoral behaviour, which is the governance concern.", C: "The platform's reputation did suffer, but that is collateral — the question asks what the pattern itself exemplifies.", D: "Ecosystem harm in this taxonomy concerns the natural environment, not metaphorically shared institutions." }, strat: "Classify by the harm mechanism the scenario centres: when profiles steer voters, the exam wants political manipulation at group and societal scale, not the incidental breach or PR damage.", trap: "too-narrow", bok: "Domain I, Competency A" },

  // F57 — ecosystem harm = natural resource depletion
  { id: "e-ddl-43", c: "i-a", type: "best", d: 2, stem: "Halcyon Compute's impact-assessment template logs AI harms at individual, group, organisational, societal and ecosystem levels. Which entry belongs at the ecosystem level?", opts: [["Depletion of natural resources — the energy, water and rare minerals consumed in training and serving large models", true], ["Regulatory fines imposed after an enforcement action", false], ["A fall in the company's share price following an AI incident", false], ["Systematically worse model outputs for one demographic group", false]], why: "Ecosystem harm in the AI-harm taxonomy means damage to the natural environment driven by AI's compute appetite: energy, water and rare-mineral extraction.", wrong: { B: "Fines land on the organisation — organisational-level harm in the taxonomy.", C: "Share price is organisational economic harm, however large the number.", D: "Demographic skew is the definition of group-level harm." }, strat: "On harm-ladder items, place each option by who or what absorbs the damage; 'ecosystem' is reserved for the natural world, not for business ecosystems.", trap: "true-but-irrelevant", bok: "Domain I, Competency A" },

  // F58 — acceleration risk vs AI exceptionalism
  { id: "e-ddl-44", c: "i-a", type: "distinction", d: 3, stem: "A retrospective at Pinnacle Robotics surfaces two cultural failures: (i) leadership raced the flagship model to market to beat a rival, consciously deferring the review of foreseeable problems until after launch; (ii) within months, operations staff had stopped questioning the system's outputs at all, reasoning that the model knows better than any of them. The correct pairing of terms is:", opts: [["(i) acceleration risk; (ii) AI exceptionalism", true], ["(i) AI exceptionalism; (ii) acceleration risk", false], ["(i) acceleration risk; (ii) anchoring bias", false], ["(i) AI exceptionalism; (ii) echo chamber", false]], why: "Racing to market ahead of foreseeing problems — the \"move fast and break things\" posture — is acceleration risk. Treating the deployed system as infallible and beyond challenge, so that staff stop questioning outputs, is AI exceptionalism. One is a pace failure before launch; the other is a deference failure after it.", wrong: { B: "Swapped: exceptionalism is the infallibility belief, not the market race.", C: "Anchoring is over-weighting the first results seen during an evaluation; blanket deference to every output is the broader treat-it-as-beyond-challenge failure.", D: "Echo chambers are recommender loops feeding users belief-consistent content; the staff's deference involves no content loop." }, strat: "Pace problems before deployment versus worship problems after it: acceleration ships too fast, exceptionalism stops the questions. Pin (i) first and the swapped option dies.", trap: "synonym-bait", bok: "Domain I, Competency A" },
];

export const examPoolDDLaw: Question[] = raw.map((r) => ({
  id: r.id,
  competencyId: r.c,
  type: r.type,
  difficulty: r.d,
  stem: r.stem,
  isMultiselect: r.multi ?? false,
  options: r.opts.map(([text, isCorrect], i) => o(String.fromCharCode(65 + i), text, isCorrect, i)),
  correctExplanation: r.why,
  whyWrong: r.wrong ?? {},
  strategyNote: r.strat,
  trapType: r.trap ?? "none",
  bokRef: r.bok,
  source: "curated",
}));
